def find_func(code, func_name):
    pattern = rf"function\s+{func_name}\s*\([^{{]*\)\s*\{{"
    m = re.search(pattern, code)
    if not m:
        return None
    start = m.start()
    brace_count = 0
    in_code = False
    for i in range(m.end() - 1, len(code)):
        if code[i] == '{':
            brace_count += 1
            in_code = True
        elif code[i] == '}':
            brace_count -= 1
            if in_code and brace_count == 0:
                return code[start:i+1]
    return code[start:start+1000]

